import {giftOnlyCards,requestGiftCards} from './chat-model.mjs?v=gift2';
import {exchangeAction,exchangeState,watchExchange,refreshExchange} from './exchange-client.mjs';
import {currentUser} from './auth-client.mjs';
const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
const preview=['localhost','127.0.0.1'].includes(location.hostname)&&new URL(location.href).searchParams.get('preview')==='1';let catalog=[];const key='exchange-requests-preview-v1';let requests=[];if(preview){try{requests=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!Array.isArray(requests))requests=[{id:'sample-received',direction:'received',person:{id:'sample-2',name:'Sample trader',online:false},give:55,receive:59,at:Date.now()}]}
const save=()=>{if(preview)try{localStorage.setItem(key,JSON.stringify(requests))}catch{}};
function dialog(title){const d=make('dialog',null,'exchange-modal'),head=make('header',null,'modal-head'),h=make('h3',title),close=make('button','Close','btn secondary'),body=make('div',null,'modal-body'),foot=make('footer',null,'modal-actions');close.type='button';close.onclick=()=>d.close();d.setAttribute('aria-label',title);head.append(h);foot.append(close);d.append(head,body,foot);document.body.append(d);return {d,h,body,foot}}
const matches=dialog('Matching cards'),pending=dialog('Pending requests');const pendingButton=make('button','Pending requests','btn secondary');pendingButton.type='button';document.querySelector('.exchange-heading').append(pendingButton);let tab='sent';
const requestLifetime=3*24*60*60*1000;
function updateCount(){if(preview)requests=requests.filter(r=>r.at>Date.now()-requestLifetime);pendingButton.textContent='Pending requests'+(requests.length?' ('+requests.length+')':'')}
function art(number,label){const card=catalog.find(c=>c.number===number),figure=make('figure',null,'exchange-art');figure.setAttribute('aria-label',label+' No. '+number);if(card){const image=make('img');image.src=new URL('./album-data/'+card.image,import.meta.url);image.alt=card.name;image.width=74;image.height=106;const stars=make('img',null,'exchange-card-stars');stars.src=new URL('./tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',import.meta.url);stars.alt=card.stars+' stars';figure.append(image,stars)}figure.append(make('strong','No. '+number,'exchange-card-number'));return figure}
function pair(give,receive){const p=make('div',null,'exchange-art-pair');p.append(art(give,'You give'),make('span','⇄','exchange-arrow'),art(receive,'You receive'));return p}

function openChat(person,text){window.dispatchEvent(new CustomEvent('card-chat-open',{detail:{...person,giftText:text}}))}
function renderPending(){pending.body.replaceChildren();const tabs=make('div',null,'segmented');for(const [value,label] of [['sent','Requests sent'],['received','Requests received']]){const b=make('button',label+' ('+requests.filter(r=>r.direction===value).length+')');b.type='button';b.setAttribute('aria-pressed',String(tab===value));b.onclick=()=>{tab=value;renderPending()};tabs.append(b)}pending.body.append(tabs,make('p','Requests expire after 3 days. Complete exchanges in game.','caption'));if(!preview&&(!exchangeState().actor||exchangeState().error)){pending.body.append(make('p',exchangeState().error||'Log in to view exchange requests.','caption'));return}const list=requests.filter(r=>r.direction===tab);for(const r of list){const box=make('article',null,'exchange-offer'),head=make('div',null,'exchange-offer-head'),button=make('button',tab==='sent'?'Recall':'Chat','btn');head.append(make('strong',r.person.name),make('span','Pending','badge'));button.type='button';button.onclick=async()=>{if(tab==='sent'){button.disabled=true;try{if(!preview)await exchangeAction('recall',{id:r.id});requests=requests.filter(x=>x.id!==r.id);save();updateCount();renderPending();if(!preview)await refreshExchange()}catch(e){button.disabled=false;pending.body.append(make('p',e.message,'caption'))}}else{pending.d.close();openChat(r.person)}};box.append(head,pair(r.give,r.receive),make('p','You give No. '+r.give+' for No. '+r.receive,'exchange-pair-description'),button);pending.body.append(box)}if(!list.length)pending.body.append(make('p',tab==='sent'?'No requests sent.':'No requests received.','caption'));if(preview)pending.body.append(make('p','Local preview · received example and sent requests are stored only in this browser.','caption'))}
pendingButton.onclick=async()=>{try{if(!preview)await refreshExchange();if(!catalog.length)catalog=(await (await fetch(new URL('./album-data/autumn-tales.json',import.meta.url))).json()).cards;renderPending();pending.d.showModal()}catch(e){pending.body.replaceChildren(make('p',e.message,'caption'));pending.d.showModal()}};
watchExchange(state=>{if(preview)return;requests=state.requests;updateCount();if(pending.d.open)renderPending()});
window.addEventListener('card-matches-open',async e=>{const {row,cards}=e.detail;catalog=cards;matches.h.textContent='Matching cards · '+row.name;matches.body.replaceChildren();const swaps=row.swaps||[];let actor=null;if(!preview)actor=await currentUser();
const myAttempts=Number(document.querySelector('#exchange-your-attempts').value),theirAttempts=row.trades_left_today;const who=make('label','Who initiates ','exchange-request-initiator'),choose=make('select');choose.setAttribute('aria-label','Request initiator');for(const [value,label,available] of [['me','I initiate',myAttempts>0],['them','They initiate',theirAttempts>0]]){const option=new Option(label,value);option.disabled=!available;choose.append(option)}const filter=document.querySelector('#exchange-filter-initiator').value;choose.value=filter|| (myAttempts>0?'me':'them');who.append(choose);if(swaps.length)matches.body.append(who);const gifts=giftOnlyCards(row),giftRequests=requestGiftCards(row);if(!swaps.length&&!gifts.length&&!giftRequests.length)matches.body.append(make('p','No matching card exchanges available.','caption'));
for(const swap of swaps){const box=make('article',null,'exchange-offer'),actions=make('div',null,'exchange-offer-actions'),request=make('button','Request','btn'),gift=make('button','Gift','btn secondary'),status=make('p',null,'caption');request.type=gift.type='button';const exists=()=>requests.some(r=>r.direction==='sent'&&r.person.id===row.id&&r.give===swap.give&&r.receive===swap.receive);request.disabled=exists()||(!preview&&!actor)||(myAttempts<1&&theirAttempts<1);request.textContent=exists()?'Requested':'Request';gift.disabled=!preview&&!actor;
request.onclick=async()=>{if(exists())return;request.disabled=true;status.textContent='';try{if(!['me','them'].includes(choose.value))throw Error('Choose who initiates.');if(preview){requests.push({id:crypto.randomUUID(),direction:'sent',person:row,give:swap.give,receive:swap.receive,at:Date.now(),initiator:choose.value});save()}else{await exchangeAction('request',{peer:row.id,give:swap.give,receive:swap.receive,season:'autumn-tales',initiator:choose.value});await refreshExchange()}updateCount();request.textContent='Requested';status.textContent=preview?'Added to Requests sent. Local preview only.':'Request sent. Both players can view it in Pending requests for 3 days.'}catch(error){status.textContent=error.message;request.disabled=false}};
gift.onclick=async()=>{gift.disabled=true;status.textContent='';try{if(!preview){await exchangeAction('gift',{peer:row.id,give:swap.give,season:'autumn-tales'});await refreshExchange()}matches.d.close();openChat(row,preview?'i have free card no. '+swap.give:undefined)}catch(error){status.textContent=error.message}finally{gift.disabled=false}};actions.append(request,gift);box.append(pair(swap.give,swap.receive),make('p','You give No. '+swap.give+' for No. '+swap.receive,'exchange-pair-description'),actions,status);matches.body.append(box)}for(const number of gifts){const box=make('article',null,'exchange-offer'),actions=make('div',null,'exchange-offer-actions'),gift=make('button','Gift','btn secondary'),status=make('p',null,'caption');gift.type='button';gift.disabled=!preview&&!actor;gift.setAttribute('aria-label','Gift card '+number);gift.onclick=async()=>{gift.disabled=true;status.textContent='';try{if(!preview){await exchangeAction('gift',{peer:row.id,give:number,season:'autumn-tales'});await refreshExchange()}matches.d.close();openChat(row,preview?'i have free card no. '+number:undefined)}catch(error){status.textContent=error.message}finally{gift.disabled=false}};actions.append(gift);box.append(art(number,'You give'),make('p','You can gift No. '+number+' · No return card needed.','exchange-pair-description'),actions,status);matches.body.append(box)}for(const number of giftRequests){const box=make('article',null,'exchange-offer'),actions=make('div',null,'exchange-offer-actions'),request=make('button','Request Gift','btn'),status=make('p',null,'caption');request.type='button';request.disabled=!preview&&!actor;request.setAttribute('aria-label','Request gift card '+number);request.onclick=async()=>{request.disabled=true;status.textContent='';try{if(!preview){await exchangeAction('request_gift',{peer:row.id,receive:number,season:'autumn-tales'});await refreshExchange()}matches.d.close();openChat(row,preview?'Could you gift me card no. '+number+'?':undefined)}catch(error){status.textContent=error.message}finally{request.disabled=false}};actions.append(request);box.append(art(number,'You need'),make('p','You need No. '+number+' · No spare they need in return.','exchange-pair-description'),actions,status);matches.body.append(box)}if(preview)matches.body.append(make('p','Local preview · requests do not reach another account yet.','caption'));matches.d.showModal()});updateCount();
